create table public.franchises (
  id uuid primary key,
  competition_id uuid not null references public.competitions(id),
  name text not null,
  code text not null,
  unique (competition_id, code),
  unique (competition_id, name)
);

create table public.cricket_players (
  id uuid primary key,
  source_id text not null unique,
  name text not null,
  role text not null check (role in ('BAT', 'BOWL', 'ALL', 'WK')),
  role_source text not null
);

create table public.season_players (
  season_id uuid not null references public.seasons(id) on delete cascade,
  player_id uuid not null references public.cricket_players(id),
  franchise_id uuid not null references public.franchises(id),
  primary key (season_id, player_id)
);

create table public.cricket_matches (
  id uuid primary key,
  season_id uuid not null references public.seasons(id) on delete cascade,
  source_id text not null unique,
  match_date date not null,
  team_a_franchise_id uuid not null references public.franchises(id),
  team_b_franchise_id uuid not null references public.franchises(id),
  venue text not null,
  status text not null check (status = 'final'),
  source_url text not null,
  source_checksum text not null,
  check (team_a_franchise_id <> team_b_franchise_id)
);

create table public.player_match_stats (
  match_id uuid not null references public.cricket_matches(id) on delete cascade,
  player_id uuid not null references public.cricket_players(id),
  franchise_id uuid not null references public.franchises(id),
  stats jsonb not null check (
    stats ?& array['runs','fours','sixes','ballsFaced','dismissed','wickets','maidens','catches','stumpings','directRunOuts','assistedRunOuts']
    and jsonb_typeof(stats) = 'object'
  ),
  source_checksum text not null,
  primary key (match_id, player_id)
);

create table public.player_match_points (
  match_id uuid not null references public.cricket_matches(id) on delete cascade,
  player_id uuid not null references public.cricket_players(id),
  scoring_version text not null,
  total_points numeric not null,
  breakdown jsonb not null check (jsonb_typeof(breakdown) = 'object'),
  primary key (match_id, player_id, scoring_version)
);

create table public.season_rounds (
  id uuid primary key,
  season_id uuid not null references public.seasons(id) on delete cascade,
  round_number integer not null check (round_number between 1 and 7),
  name text not null,
  stage text not null check (stage in ('regular', 'semifinal', 'final')),
  starts_on date not null,
  ends_on date not null check (ends_on >= starts_on),
  unique (season_id, round_number)
);

create table public.season_round_matches (
  round_id uuid not null references public.season_rounds(id) on delete cascade,
  match_id uuid not null unique references public.cricket_matches(id) on delete cascade,
  primary key (round_id, match_id)
);

create table public.season_pairings (
  season_id uuid not null references public.seasons(id) on delete cascade,
  round_number integer not null check (round_number between 1 and 5),
  home_position integer not null check (home_position between 1 and 6),
  away_position integer not null check (away_position between 1 and 6 and away_position <> home_position),
  primary key (season_id, round_number, home_position),
  unique (season_id, round_number, away_position)
);

create table public.cricket_ingest_runs (
  id uuid primary key,
  season_id uuid not null references public.seasons(id) on delete cascade,
  source_url text not null,
  checksum text not null unique,
  source_version text not null,
  attribution text not null,
  license_url text not null,
  role_policy text not null,
  imported_at timestamptz not null default now()
);

create index season_players_franchise_idx on public.season_players(season_id, franchise_id);
create index cricket_matches_season_date_idx on public.cricket_matches(season_id, match_date);
create index player_match_stats_player_idx on public.player_match_stats(player_id, match_id);
create index player_match_points_player_idx on public.player_match_points(player_id, match_id, scoring_version);
create index season_rounds_season_idx on public.season_rounds(season_id, round_number);

alter table public.franchises enable row level security;
alter table public.cricket_players enable row level security;
alter table public.season_players enable row level security;
alter table public.cricket_matches enable row level security;
alter table public.player_match_stats enable row level security;
alter table public.player_match_points enable row level security;
alter table public.season_rounds enable row level security;
alter table public.season_round_matches enable row level security;
alter table public.season_pairings enable row level security;
alter table public.cricket_ingest_runs enable row level security;

revoke all on public.franchises, public.cricket_players, public.season_players,
  public.cricket_matches, public.player_match_stats, public.player_match_points,
  public.season_rounds, public.season_round_matches, public.season_pairings,
  public.cricket_ingest_runs from public, anon;
grant select on public.franchises, public.cricket_players, public.season_players,
  public.cricket_matches, public.player_match_stats, public.player_match_points,
  public.season_rounds, public.season_round_matches, public.season_pairings,
  public.cricket_ingest_runs to authenticated;

create policy franchises_authenticated_read on public.franchises for select to authenticated using (true);
create policy cricket_players_authenticated_read on public.cricket_players for select to authenticated using (true);
create policy season_players_authenticated_read on public.season_players for select to authenticated using (true);
create policy cricket_matches_authenticated_read on public.cricket_matches for select to authenticated using (true);
create policy player_match_stats_authenticated_read on public.player_match_stats for select to authenticated using (true);
create policy player_match_points_authenticated_read on public.player_match_points for select to authenticated using (true);
create policy season_rounds_authenticated_read on public.season_rounds for select to authenticated using (true);
create policy season_round_matches_authenticated_read on public.season_round_matches for select to authenticated using (true);
create policy season_pairings_authenticated_read on public.season_pairings for select to authenticated using (true);
create policy cricket_ingest_runs_authenticated_read on public.cricket_ingest_runs for select to authenticated using (true);
do $$
declare
  target_season uuid;
begin
  select s.id into target_season
  from public.seasons s join public.competitions c on c.id = s.competition_id
  where c.slug = 'mlc' and s.year = 2026;
  if target_season is null then
    raise exception 'Expected existing MLC 2026 season';
  end if;
end $$;


