  insert into public.season_pairings(season_id,round_number,home_position,away_position)
  select v_season,x.round_number,x.home_position,x.away_position from jsonb_to_recordset($pairings$[{"round_number":1,"home_position":1,"away_position":6},{"round_number":1,"home_position":2,"away_position":5},{"round_number":1,"home_position":3,"away_position":4},{"round_number":2,"home_position":5,"away_position":1},{"round_number":2,"home_position":4,"away_position":6},{"round_number":2,"home_position":3,"away_position":2},{"round_number":3,"home_position":1,"away_position":4},{"round_number":3,"home_position":5,"away_position":3},{"round_number":3,"home_position":6,"away_position":2},{"round_number":4,"home_position":3,"away_position":1},{"round_number":4,"home_position":2,"away_position":4},{"round_number":4,"home_position":6,"away_position":5},{"round_number":5,"home_position":1,"away_position":2},{"round_number":5,"home_position":3,"away_position":6},{"round_number":5,"home_position":4,"away_position":5}]$pairings$::jsonb) as x(round_number integer,home_position integer,away_position integer)
  on conflict(season_id,round_number,home_position) do update set away_position=excluded.away_position;
