  if v_rows <> 15 then raise exception 'Cricsheet pairing upsert incomplete'; end if;
  insert into public.cricket_ingest_runs(id,season_id,source_url,checksum,source_version,attribution,license_url,role_policy)
  select x.id,v_season,x.source_url,x.checksum,x.source_version,x.attribution,x.license_url,x.role_policy
  from jsonb_to_recordset($ingest$[{"id":"9cffb93b-db1a-52bd-bab0-850a15e40d21","source_url":"https://cricsheet.org/downloads/mlc_json.zip","checksum":"0e54cad247f1f26e7ee803f6e69ce6100166e66022f3ac5818e227855502db0b","source_version":"Cricsheet JSON 1.3.0","attribution":"Cricsheet, Major League Cricket JSON data; https://cricsheet.org/","license_url":"https://opendatacommons.org/licenses/by/1.0/","role_policy":"mlc-2026-v2: fantasy-derived, not a complete official-role dataset. WK classifications use official 2026 franchise player pages explicitly listing the person as a wicketkeeper; all other roles derive from 2026 match contributions: ALL when both (runs >= 20 or balls faced >= 15) and (credited wickets > 0 or maiden > 0), BOWL when bowling evidence exists, otherwise BAT. Source URL is retained in each official WK player's role_source."}]$ingest$::jsonb)
    as x(id uuid,source_url text,checksum text,source_version text,attribution text,license_url text,role_policy text)
  on conflict(checksum) do update set source_version=excluded.source_version,attribution=excluded.attribution,license_url=excluded.license_url,role_policy=excluded.role_policy,imported_at=now();
  get diagnostics v_rows = row_count;
  if v_rows <> 1 then raise exception 'Cricsheet ingest audit upsert incomplete'; end if;
  if (select count(*) from public.cricket_matches where season_id=v_season) <> 34 then raise exception 'Cricsheet match seed count mismatch'; end if;
  if (select count(*) from public.player_match_stats p join public.cricket_matches m on m.id=p.match_id where m.season_id=v_season) <> 754 then raise exception 'Cricsheet stat seed count mismatch'; end if;
